    public static function render($name, $class = '', $size = 18, $strokeWidth = 2)
    {
        $path = self::$icons[$name] ?? self::$icons['info'];
        $classAttr = 'ui-icon' . ($class ? ' ' . htmlspecialchars($class, ENT_QUOTES, 'UTF-8') : '');
        $sizeAttr = (int) $size;
        $strokeAttr = (float) $strokeWidth;

        return sprintf(
            '<svg class="%s" width="%d" height="%d" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="%.1f" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">%s</svg>',
            $classAttr,
            $sizeAttr,
            $sizeAttr,
            $strokeAttr,
            $path
        );
    }
